import{_ as i,o as r,c as t,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"Untitled","description":"","frontmatter":{"title":"Untitled","date":"2014-10-30T00:00:00.000Z","updated":"2014-10-30T00:00:00.000Z","tags":["CephFS","Forward Scrub","Reverse Scrub","Metadata Integrity","Ceph Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_Hammer_Day_2_-_CephFS_-_Forward_Scrub.md","filePath":"posts/2014/CDS_Hammer_Day_2_-_CephFS_-_Forward_Scrub.md","lastUpdated":1780459816000}'),a={name:"posts/2014/CDS_Hammer_Day_2_-_CephFS_-_Forward_Scrub.md"};function o(s,l,_,n,p,g){return r(),t("div",null,[...l[0]||(l[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年（具体日期未提及）</p><p><strong>会议主题</strong>： SEFS 前向清理和反向清理（修复）的进展讨论</p><p><strong>参会人员</strong>： Craig、Greg、John、Sage等</p><p><strong>会议内容</strong>：</p><p><strong>1. 前向清理进展</strong></p><ul><li>Craig 和 Greg 负责的前向清理工作已进行一年半，目前已开始实际工作。</li><li>前向清理从文件系统层次结构的根开始，递归检查所有元数据，确保其自洽性。</li><li>已提交代码审查，包括提升 MDS 内部操作至客户端请求同等级别，验证 iode 代码和 admin socket 接口。</li><li>正在开发“scrub 栈”，将算法转换为实际可工作的代码，但尚未准备好提交 PR。</li></ul><p><strong>2. 反向清理进展</strong></p><ul><li>John 和 Sage 讨论了反向清理的组件，包括： <ul><li>使用 pgls 过滤器查找丢失的目录对象，并将恢复路径直接插入后端存储。</li><li>在运行中的 MDS 中插入恢复的元数据，避免关闭整个文件系统。</li><li>创建对象类处理清理过程中的对象。</li><li>在清理前备份元数据池，以便失败时回滚。</li><li>使用 Rados 导出/导入工具或池快照进行备份。</li></ul></li></ul><p><strong>3. 清理错误处理</strong></p><ul><li>讨论了如何向管理员展示清理错误，以便修复。</li><li>提出使用健康检查系统跟踪错误，并使用结构化日志记录错误信息。</li><li>讨论了使用内存中的数据结构跟踪错误，避免覆盖已知正确数据。</li></ul><p><strong>4. 下一步行动</strong></p><ul><li>John 和 Sage 继续开发反向清理代码。</li><li>Craig 和 Greg 完成前向清理代码的审查和提交。</li><li>所有参与者继续讨论清理错误处理，确保系统稳定性和数据完整性。</li></ul><p><strong>关键词</strong>：</p><ul><li>SEFS</li><li>前向清理</li><li>反向清理</li><li>MDS</li><li>iode</li><li>pgls 过滤器</li><li>Rados</li><li>健康检查</li><li>结构化日志</li><li>元数据完整性</li></ul>',15)])])}const u=i(a,[["render",o]]);export{S as __pageData,u as default};
